contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(bytes32 newHash) public payable {
        bytes32 beforeHash = c.hash(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.setL1BlockValues(uint64(1), uint64(1), 1, newHash, uint64(1), bytes32(0), 1, 1); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted && c.hash() == beforeHash);
    }

    receive() external payable {}
}

