pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(bytes32 newHash) internal {
        bytes32 beforeHash;
        try c.hash() returns (bytes32 __r) { beforeHash = __r; } catch { return; }
        bool reverted;
        try c.setL1BlockValues(uint64(1), uint64(1), 1, newHash, uint64(1), bytes32(0), 1, 1) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted && c.hash() == beforeHash);
    }

    function testFuzz_run(bytes32 newHash) public {
        _run(newHash);
    }

    receive() external payable {}
}
